nodes.text:
exportData && username ? (
        <ExportData owner={username} />
      ) : appearance ? (
        <Appearance />
      ) : route === "/" ? (
        <Today />
      ) : route === "/proyectos/nuevo" ? (
        <CreateProjectScreen />
      ) : weeklyReview ? (
        <WeeklyReview route={route} />
      ) : history ? (
        <History route={route} />
      ) : availability ? (
        <Availability />
      ) : sessionRoute ? (
        <WorkSessionReader
          key={route}
          projectId={sessionRoute[1]}
          taskId={sessionRoute[2]}
          id={sessionRoute[3]}
        />
      ) : taskRoute ? (
        <TaskReader
          key={route}
          projectId={taskRoute[1]}
          id={taskRoute[2]}
          customization={customization}
        />
      ) : /^\/proyectos\/[^/?]+\/editar$/.test(route) ? (
        <ProjectEditor key={route} route={route} />
      ) : /^\/proyectos(?:\?[^#]*|\/[^/?]+)?$/.test(route) ? (
        <ProjectReader
          key={route}
          route={route}
          customization={customization}
        />
      ) : (
        <main id="proyectos" tabIndex={-1}>
          <h1>Página no encontrada</h1>
          <RouteLink href="/">Hoy</RouteLink>
          {" · "}
          <RouteLink href="/proyectos">Proyectos</RouteLink>
        </main>
      )
